// Shared locale selection. Explicit links and manual preferences take priority.
const localeNames={pt:'Português',es:'Español',en:'English'};
function initialLanguage(){
 const explicit=new URLSearchParams(location.search).get('lang');
 if(localeNames[explicit])return explicit;
 try{const saved=localStorage.getItem('cheers-language');if(localeNames[saved])return saved;}catch{}
 const preferred=(navigator.languages?.[0]||navigator.language||'en').toLowerCase().split('-')[0];
 return localeNames[preferred]?preferred:'en';
}
function rememberLanguage(lang){try{localStorage.setItem('cheers-language',lang);}catch{}}
function languageButtons(lang){return `<div class="language" aria-label="Language">${['pt','es','en'].map(l=>`<button type="button" data-lang="${l}" lang="${l}" aria-label="${localeNames[l]}" aria-pressed="${lang===l}" class="${lang===l?'active':''}">${l.toUpperCase()}</button>`).join('<span aria-hidden="true">/</span>')}</div>`;}
function localLabel(lang,pt,es,en){return {pt,es,en}[lang];}
